const POLE_TOPOLOGY = {
    "Single Dipole": 2,
    "Opposing Pair": 4,
    "Triangular Vortex": 3,
    "Quadrupole Cross": 4,
    "Pentagonal Ring": 5,
    "Chaotic Multipole": 8
};

const FIELD_VISCOSITY = {
    "Silk Streamlines": { steps: 16, spike: 0.0, stepSize: 8 },
    "Viscous Honey": { steps: 12, spike: 0.2, stepSize: 10 },
    "Tense Membrane": { steps: 8, spike: 0.5, stepSize: 15 },
    "Brittle Spikes": { steps: 5, spike: 1.2, stepSize: 24 },
    "Ferro Needles": { steps: 3, spike: 2.5, stepSize: 36 },
    "Fractured Shards": { steps: 2, spike: 4.0, stepSize: 50 }
};

const FLUX_DENSITY = {
    "Sparse Filaments": 220,
    "Woven Strands": 320,
    "Braided Ribbons": 440,
    "Dense Currents": 580,
    "Solid Saturation": 720,
    "Total Eclipse": 880
};

const KINETIC_SURGE = {
    "Drifting Orbit": 0.002,
    "Pulsing Tide": 0.005,
    "Turbulent Swirl": 0.01,
    "Whipping Shear": 0.02,
    "Resonant Flutter": 0.035,
    "Seismic Roar": 0.06
};

const CHROMA_TEMPER = {
    "Iron Hematite": { bg: "#080808", c1: "#3b3b3b", c2: "#8a8a8a" },
    "Cobalt Steel": { bg: "#040811", c1: "#1a467b", c2: "#4c8de6" },
    "Bismuth Sheen": { bg: "#0c0312", c1: "#8a2be2", c2: "#00ffcc" },
    "Copper Patina": { bg: "#0d0603", c1: "#b87333", c2: "#45a27d" },
    "Molten Magma": { bg: "#140300", c1: "#cc2900", c2: "#ffb300" },
    "Solar Flare": { bg: "#171300", c1: "#ffaa00", c2: "#ffffff" }
};

let particles = [];
let poles = [];
let currentDensity = 0;
let currentTopology = "";

p.setup = function() {
    p.createCanvas(800, 800);
    p.noFill();
};

p.draw = function() {
    const topologyStr = p.getSynthVar('pole_topology') || "Single Dipole";
    const viscosityStr = p.getSynthVar('field_viscosity') || "Silk Streamlines";
    const fluxStr = p.getSynthVar('flux_density') || "Sparse Filaments";
    const surgeStr = p.getSynthVar('kinetic_surge') || "Drifting Orbit";
    const chromaStr = p.getSynthVar('chroma_temper') || "Iron Hematite";

    const poleCount = POLE_TOPOLOGY[topologyStr];
    const viscConfig = FIELD_VISCOSITY[viscosityStr];
    const targetDensity = FLUX_DENSITY[fluxStr];
    const surgeSpeed = KINETIC_SURGE[surgeStr];
    const palette = CHROMA_TEMPER[chromaStr];

    if (topologyStr !== currentTopology) {
        poles = [];
        for (let i = 0; i < poleCount; i++) {
            poles.push({
                angle: (p.TWO_PI / poleCount) * i,
                radius: p.random(120, 280),
                polarity: (i % 2 === 0) ? 1 : -1,
                phase: p.random(p.TWO_PI)
            });
        }
        currentTopology = topologyStr;
    }

    if (targetDensity !== currentDensity) {
        if (targetDensity > currentDensity) {
            for (let i = currentDensity; i < targetDensity; i++) {
                particles.push({
                    x: p.random(p.width),
                    y: p.random(p.height),
                    life: p.random(50, 150)
                });
            }
        } else {
            particles.splice(targetDensity);
        }
        currentDensity = targetDensity;
    }

    let t = p.frameCount * surgeSpeed;
    for (let i = 0; i < poles.length; i++) {
        poles[i].x = 400 + p.cos(poles[i].angle + t + poles[i].phase) * poles[i].radius * (1 + 0.2 * p.sin(t * 1.5));
        poles[i].y = 400 + p.sin(poles[i].angle + t * 1.2 + poles[i].phase) * poles[i].radius * (1 + 0.2 * p.cos(t * 1.5));
    }

    p.background(palette.bg);

    p.strokeWeight(p.map(currentDensity, 220, 880, 4.0, 0.8));

    let grad = p.drawingContext.createLinearGradient(0, 0, 800, 800);
    grad.addColorStop(0, palette.c1);
    grad.addColorStop(1, palette.c2);
    p.drawingContext.strokeStyle = grad;

    p.drawingContext.beginPath();
    let batchCount = 0;

    for (let i = 0; i < currentDensity; i++) {
        let pt = particles[i];
        let cx = pt.x;
        let cy = pt.y;

        p.drawingContext.moveTo(cx, cy);

        for (let step = 0; step < viscConfig.steps; step++) {
            let fx = 0;
            let fy = 0;

            for (let p_idx = 0; p_idx < poles.length; p_idx++) {
                let pl = poles[p_idx];
                let dx = cx - pl.x;
                let dy = cy - pl.y;
                let distSq = dx * dx + dy * dy + 200; 
                let force = (1200 * pl.polarity) / distSq;
                fx += dx * force;
                fy += dy * force;
            }

            let mag = p.sqrt(fx * fx + fy * fy) + 0.0001;

            if (viscConfig.spike > 0) {
                let jitterX = p.sin(cx * 0.05 + t * 10) * p.cos(cy * 0.05);
                let jitterY = p.cos(cx * 0.05 - t * 10) * p.sin(cy * 0.05);
                fx += jitterX * viscConfig.spike * mag;
                fy += jitterY * viscConfig.spike * mag;
                mag = p.sqrt(fx * fx + fy * fy) + 0.0001;
            }

            cx += (fx / mag) * viscConfig.stepSize;
            cy += (fy / mag) * viscConfig.stepSize;

            p.drawingContext.lineTo(cx, cy);
        }

        batchCount++;
        if (batchCount % 200 === 0) {
            p.drawingContext.stroke();
            p.drawingContext.beginPath();
        }

        pt.life--;
        if (pt.life <= 0 || pt.x < 0 || pt.x > p.width || pt.y < 0 || pt.y > p.height) {
            pt.x = p.random(p.width);
            pt.y = p.random(p.height);
            pt.life = p.random(50, 150);
        } else {
            pt.x += p.sin(pt.y * 0.02 + t * 2) * 2;
            pt.y += p.cos(pt.x * 0.02 + t * 2) * 2;
        }
    }

    if (batchCount % 200 !== 0) {
        p.drawingContext.stroke();
    }
};
